"""Generate an isolated owner-review proposal. Never imports application code."""
from pathlib import Path
import json
from html import escape

HERE = Path(__file__).resolve().parent
BASE = '5355ae5b12bb86ed2c05f70fcadd77eadcd7bde3'
FIXTURE = json.loads((HERE.parent / 'visual-directions-v2/evidence/synthetic-fixture.json').read_text())
(HERE / 'evidence/synthetic-fixture.json').write_text(json.dumps(FIXTURE, ensure_ascii=False, indent=2) + '\n')
INVENTORY = []

def write(name, content):
    (HERE / name).write_text(content, encoding='utf-8')

def icon(name):
    paths = {
        'calendar': '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h3m3 0h2"/>',
        'document': '<path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6m-6 4h6"/>',
        'arrow': '<path d="M4 12h15m-5-5 5 5-5 5"/>',
        'search': '<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
        'people': '<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v3"/>',
        'clock': '<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
        'lock': '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',
        'location': '<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
        'check': '<path d="m5 12 4 4 10-10"/>',
        'warning': '<path d="m12 3 10 18H2Z M12 9v5m0 3v1"/>',
        'history': '<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2"/>',
        'rx': '<path d="M5 20V4h5a5 5 0 0 1 0 10H5m6 0 8 7m-1-8-7 8"/>',
    }
    return f'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">{paths[name]}</svg>'

def pick(lang, ar, en):
    return ar if lang == 'ar' else en

def badge(text, tone='neutral'):
    return f'<span class="badge {tone}">{text}</span>'

def action(text, kind='primary', preview='appointment', ico='arrow'):
    return f'<button type="button" class="button {kind}" data-preview="{preview}">{text}{icon(ico)}</button>'

def muted(text):
    return f'<p class="muted">{text}</p>'

def page(name, title, content, lang='en', cls='review', extra=''):
    direction = 'rtl' if lang == 'ar' else 'ltr'
    write(name, f'''<!doctype html>
<html lang="{lang}" dir="{direction}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} · EgyHealth 360 review</title><link rel="stylesheet" href="tokens.css"><link rel="stylesheet" href="review.css"><script src="review.js" defer></script></head>
<body class="{cls}"><a class="skip" href="#main">{pick(lang,'روح للمحتوى','Skip to content')}</a>{content}{extra}</body></html>''')
    INVENTORY.append({'path': name, 'language': lang, 'class': cls})


def preview_dialog(lang):
    return f'''<dialog id="preview" aria-labelledby="dialog-title"><form method="dialog"><button class="dialog-close button secondary">{pick(lang,'اقفل','Close')} ×</button></form><p class="eyebrow">{pick(lang,'عرض تجريبي · بيانات افتراضية','Demo · synthetic data')}</p><h2 id="dialog-title">{pick(lang,'تفاصيل الميعاد','Appointment details')}</h2><div id="dialog-content"></div></dialog>'''


def shell(role, lang, variant, content):
    t = lambda a, e: pick(lang, a, e)
    labels = {'patient':t('متابعتي','My care'), 'clinician':t('جدول المواعيد','Schedule'), 'pharmacy':t('الوصفات المسندة','Assigned work'), 'laboratory':t('الفحوصات المسندة','Assigned diagnostics'), 'admin':t('الأشخاص','People')}
    second = {'patient':t('دور على دكتور','Find care'), 'clinician':t('مرضاي','People in your care'), 'pharmacy':t('سجل الصرف','Dispense history'), 'laboratory':t('السجل المتاح','Available history'), 'admin':t('الجهات','Organizations')}
    other = 'en' if lang == 'ar' else 'ar'
    initials = {'patient':'OA','clinician':'MH','pharmacy':'PS','laboratory':'LS','admin':'AD'}[role]
    return f'''<div class="review-strip"><a href="index.html">{t('مراجعة الاتجاهات','Direction review')}</a><span><bdi dir="ltr">{'H · Human Precision' if variant == 'h' else 'P · Precision, Open'}</bdi> · {t('مقترح غير معتمد','Unselected proposal')}</span><a href="{variant}-{role}-{other}.html" lang="{other}">{'English' if lang == 'ar' else 'العربية'}</a></div>
<div class="product-shell"><header class="product-header"><a class="wordmark" href="{variant}-patient-{lang}.html" dir="ltr">EgyHealth <span>360</span></a><nav class="primary-nav" aria-label="{t('التنقل الرئيسي','Primary navigation')}"><a href="#main" aria-current="page">{icon('calendar' if role in ['patient','clinician'] else 'document')}{labels[role]}</a><button class="nav-preview" data-preview="navigation">{icon('search' if role == 'patient' else 'people')}{second[role]}</button></nav><div class="account"><span class="demo-label">{t('عرض تجريبي','Demo')}</span><span class="avatar" aria-label="{t('حساب افتراضي','Synthetic account')}">{initials}</span></div></header><div class="product-content">{content}</div></div>
<footer class="product-footer"><span dir="ltr">© 2026 EgyHealth 360</span><span>{t('بيانات افتراضية فقط · مفيش اتصال بخدمة فعلية','Synthetic data only · no Live service connected')}</span><a href="specimen-{lang}.html">{t('المكوّنات والحالات','Components & states')}</a></footer>{preview_dialog(lang)}'''


def appointment(lang):
    t = lambda a,e: pick(lang,a,e)
    return f'''<section class="appointment" aria-labelledby="appointment-heading"><div class="section-line"><h2 class="eyebrow" id="appointment-heading">{t('ميعادك الجاي','Your next appointment')}</h2>{badge(t('محجوز','Booked'),'inverse')}</div><div class="appointment-core"><div class="calendar-tile" aria-label="{t('2 نوفمبر','2 November')}"><strong>02</strong><span>{t('نوفمبر','NOV')}</span></div><div class="appointment-person"><h3>{t('د. مريم حسن','Dr Mariam Hassan')}</h3><p>{t('باطنة · عيادة الدقي','Internal medicine · Dokki Clinic')}</p><p class="appointment-time"><bdi dir="ltr">14:30</bdi> · {t('الاثنين، 2 نوفمبر 2026','Monday, 2 November 2026')}</p></div></div><p class="zone">{t('توقيت العيادة','Clinic time')} · <bdi dir="ltr">Africa/Cairo · UTC+02:00</bdi></p><div class="appointment-bottom">{action(t('شوف تفاصيل الميعاد','View appointment'),'on-dark')}{icon('location')}<span>{t('في العيادة','In person')}</span></div><p class="authority">{t('الحجز لوحده مش بيدي الدكتور صلاحية يشوف معلوماتك الطبية.','Booking alone does not give the doctor access to your medical information.')}</p></section>'''


def next_step(lang):
    t = lambda a,e: pick(lang,a,e)
    return f'''<section class="next-step" aria-labelledby="next-heading"><p class="eyebrow">{t('خطوتك الجاية','Next for you')}</p><h2 id="next-heading">{t('راجع ملخص زيارتك','Read your visit summary')}</h2><p>{t('د. مريم حسن شاركت معاك ملخص الزيارة. التعليمات زي ما الدكتور كتبها.','Dr Mariam Hassan shared your visit summary. Read the instructions as recorded by your doctor.')}</p>{action(t('اقرأ الملخص','Read summary'),'text','summary','document')}<div class="followup"><strong>{t('الدكتور موصي بمتابعة','Follow-up recommended')}</strong>{muted(t('مفيش ميعاد مرتبط بالتوصية هنا. التوصية مش حجز.','No appointment is linked here. A recommendation is not a booking.'))}{action(t('دور على ميعاد','Find an appointment'),'secondary','navigation','calendar')}</div></section>'''


def retrieval(lang):
    t=lambda a,e:pick(lang,a,e)
    items=[('calendar',t('مواعيدك','Appointments')),('rx',t('روشتاتك','Prescriptions')),('document',t('الملخصات والمتابعة','Summaries & follow-up')),('history',t('السجل المتاح','Available history')),('people',t('دكاترتي','Your doctors'))]
    return f'''<section class="retrieval" aria-labelledby="retrieval-heading"><div class="section-line"><h2 id="retrieval-heading">{t('معلوماتك في لمحة','Your information')}</h2><span class="muted">{t('المصادر المتاحة بس','Available sources only')}</span></div><div class="retrieval-list">{''.join(f'<button data-preview="retrieval" class="retrieval-item">{icon(i)}<span>{label}</span>{icon("arrow")}</button>' for i,label in items)}</div></section>'''


def recent(lang):
    t=lambda a,e:pick(lang,a,e)
    return f'''<section class="recent" aria-labelledby="recent-heading"><div class="section-line"><h2 id="recent-heading">{t('آخر المتابعات','Recently shared')}</h2><span class="muted">{t('من دكاترتك','From your doctors')}</span></div><article class="source-row"><span class="source-icon">{icon('document')}</span><div><h3>{t('ملخص الزيارة','Visit summary')}</h3><p>{t('د. مريم حسن · 1 نوفمبر 2026','Dr Mariam Hassan · 1 November 2026')}</p><span class="muted">{t('مصدر مستقل · نسخة موقّعة','Independent source · signed version')}</span></div>{badge(t('متشارك معاك','Shared with you'),'success')}{action(t('افتح الملخص','Read summary'),'text','summary')}</article><p class="privacy-caption">{icon('lock')}{t('هنا بيظهر اللي الدكتور شاركه معاك بس. الملاحظات الخاصة بتفضل خاصة.','Only information shared with you appears here. Private notes stay private.')}</p></section>'''


def patient(lang, variant):
    t=lambda a,e:pick(lang,a,e)
    heading=f'''<div class="page-heading"><div><p class="eyebrow">{t('متابعتي','My care')} · {t('2 نوفمبر 2026','2 November 2026')}</p><h1>{t('صباح الخير يا عمر','Good morning, Omar')}</h1><p>{t('ميعادك، وآخر اللي الدكتور شاركه معاك.','Your next visit, and what your doctor shared.')}</p></div><span class="quiet-label">{t('كل خطوة واضحة','Each step, in context')}</span></div>'''
    content=f'<main id="main" class="workspace patient-workspace">{heading}<div class="patient-top">{appointment(lang)}{next_step(lang)}</div>{retrieval(lang)}{recent(lang)}</main>'
    page(f'{variant}-patient-{lang}.html',t('متابعتي','My care'),shell('patient',lang,variant,content),lang,f'product candidate-{variant} role-patient')


def clinician(lang, variant):
    t=lambda a,e:pick(lang,a,e)
    tasks=[('note',t('الملاحظة الخاصة','Private note')),('summary',t('ملخص الزيارة','Patient summary')),('followup',t('تعليمات المتابعة','Follow-up instructions')),('close',t('المراجعة والإغلاق','Review & close'))]
    ribbon=f'''<section class="visit-ribbon" aria-labelledby="visit-name"><div class="visit-person"><span class="avatar">OA</span><div><p class="eyebrow">{t('المريض والزيارة','Patient & visit')}</p><h1 id="visit-name">{t('عمر عبدالرحمن','Omar Abdelrahman')}</h1><span><bdi dir="ltr">EH-DEMO-204</bdi> · {t('عيادة الدقي','Dokki Clinic')}</span></div></div><div class="visit-meta"><p>{t('2 نوفمبر 2026','2 November 2026')} · <bdi dir="ltr">14:30</bdi></p><p><bdi dir="ltr">Africa/Cairo · UTC+02:00</bdi></p></div><div class="visit-status">{badge(t('الاستشارة مفتوحة','Consultation open'),'inverse')}<span>{t('رعاية حالية · مثال افتراضي','Current assignment · specimen')}</span></div></section>'''
    nav=f'<nav class="local-nav" aria-label="{t("مهام الزيارة","Consultation tasks")}">{"".join(f"<a href=\"#{key}\">{label}</a>" for key,label in tasks)}</nav>'
    warning=f'''<div class="notice warning" role="note">{icon('warning')}<div><strong>{t('الحساسية لسه متراجعتش','Allergies not reviewed')}</strong><p>{t('ده مش معناه مفيش حساسية معروفة. راجعها في مساحة العمل الفعلية.','This does not mean no known allergies. Review in the connected workspace.')}</p></div></div>'''
    note=f'''<section class="note-editor" id="note"><div class="section-line"><h2>{icon('lock')}{t('الملاحظة الخاصة','Private note')}</h2>{badge(t('مسودة محفوظة','Saved draft'))}</div><p class="audience">{t('خاصة بالمؤلف · حسب صلاحية الرعاية الحالية','Author only · subject to current clinical authority')}</p><label for="findings">{t('الشكوى والملاحظات','Complaint & findings')}</label><textarea id="findings" readonly aria-describedby="note-help" rows="5">{t('نص سريري افتراضي كتبه الدكتور للتجربة. يفضل خاص ومش بيتنسخ تلقائيًا لملخص المريض.','Synthetic clinician-authored text for this review. Remains private and is never automatically copied to a patient summary.')}</textarea><p class="field-help" id="note-help">{t('عرض للقراءة بس. التوقيع مش بيشارك الملاحظة مع المريض.','Read-only specimen. Signing does not share this note with the patient.')}</p><div class="button-row"><button class="button secondary" disabled>{t('احفظ المسودة','Save draft')}</button>{action(t('راجع توقيع الملاحظة الخاصة','Review private-note signing'),'primary','sign','lock')}</div><p class="field-help">{t('حفظ وتوقيع فعلي مش متاحين في العرض ده.','Actual saving and signing are unavailable in this review.')}</p></section>'''
    summary=f'''<section class="summary-source" id="summary"><div class="section-line"><h2>{t('ملخص الزيارة','Patient summary')}</h2>{badge(t('مسودة · لسه متشاركتش','Draft · not shared'))}</div><p>{t('مصدر مستقل عن الملاحظة الخاصة. المريض يشوفه بس بعد التوقيع والمشاركة الصريحة.','A separate source from the private note. Visible to the patient only after explicit signing and release.')}</p>{action(t('راجع حدود المشاركة','Review release boundary'),'text','release','document')}</section>'''
    sidebar=f'''<aside class="source-rail" aria-labelledby="sources-heading"><h2 id="sources-heading">{t('حالة المصادر','Source states')}</h2><dl><div><dt>{t('الملاحظة الخاصة','Private note')}</dt><dd>{t('مسودة محفوظة · خاصة','Saved draft · private')}</dd></div><div><dt>{t('ملخص المريض','Patient summary')}</dt><dd>{t('مسودة · غير مشارَكة','Draft · not released')}</dd></div><div><dt>{t('المتابعة','Follow-up')}</dt><dd>{t('لسه متكتبتش','Not authored')}</dd></div></dl><details><summary>{t('المصدر والتاريخ','Source & chronology')}</summary><p>{t('د. مريم حسن · مسودة 2 نوفمبر 2026','Dr Mariam Hassan · draft of 2 November 2026')}</p><p><bdi dir="ltr">14:42 · Africa/Cairo · UTC+02:00</bdi></p></details><p class="field-help">{t('الحجز لوحده مش بيدي صلاحية سريرية. الصلاحية الحالية لازم تتراجع مع كل إجراء.','Booking alone grants no clinical authority. Current authority must be checked for every operation.')}</p></aside>'''
    followup=f'''<section id="followup" class="followup-source"><h2>{t('تعليمات المتابعة','Follow-up instructions')}</h2><p>{t('مصدر مستقل، ومشاركته خطوة مستقلة. التوصية مش ميعاد محجوز.','An independent source with its own release. A recommendation is not a booked appointment.')}</p>{badge(t('لسه متكتبتش','Not authored'))}</section>'''
    closing=f'''<section id="close" class="close-section"><div><h2>{t('المراجعة والإغلاق','Review & close consultation')}</h2><p>{t('الإغلاق نهائي. مش بيحفظ أو يوقّع أو يشارك أي مصدر تلقائيًا.','Closing is irreversible. It does not automatically save, sign or release any source.')}</p></div>{action(t('راجع أثر الإغلاق','Review close consequences'),'secondary','close')}</section>'''
    mobile=f'''<section class="mobile-clinical notice"><div><h2>{t('سياق الزيارة على الموبايل','Visit context on mobile')}</h2><p>{t('راجع الهوية والزيارة وحالة المصادر. التوثيق والتوقيع والإغلاق محتاجين مساحة العمل الكاملة المتصلة.','Review identity, visit and source states. Documentation, signing and closing need the full connected workspace.')}</p></div></section>'''
    content=f'<main id="main" class="workspace clinician-workspace">{ribbon}{nav}{warning}{mobile}<div class="clinical-grid"><div>{note}{summary}{followup}</div>{sidebar}</div>{closing}</main>'
    page(f'{variant}-clinician-{lang}.html',t('الاستشارة الحالية','Active consultation'),shell('clinician',lang,variant,content),lang,f'product candidate-{variant} role-clinician')


def operations(role,lang,variant):
    t=lambda a,e:pick(lang,a,e)
    if role=='pharmacy':
        heading=t('الوصفات المسندة لصيدليتك','Assigned to your pharmacy')
        intro=t('نفس الهوية، وكثافة مناسبة للشغل المعيّن. مفيش تصفّح لملف المريض.','One identity, with density for assigned work. No patient-chart browsing.')
        body=f'''<div class="section-line"><h2>{t('وصفة مسندة · بيانات افتراضية','Routed prescription · synthetic example')}</h2>{badge(t('المسؤولية مقبولة','Responsibility accepted'),'success')}</div><article class="work-item"><span class="source-icon">{icon('rx')}</span><div><h3><bdi dir="ltr">Amoxicillin</bdi></h3><p>{t('كمية عرض افتراضية، مش جرعة','Synthetic display quantity, not a dosage')}: <bdi dir="ltr">1.25 mL</bdi></p><p>{t('مفيش صرف مسجّل. المخزون أو جاهزية الاستلام مش مؤكّدين.','No dispense recorded. Stock or pickup readiness is not confirmed.')}</p></div>{badge(t('الصرف مش مسجّل','No dispense recorded'))}</article><p>{t('الصلاحية: من 2 نوفمبر 2026، 14:20 إلى 5 نوفمبر 2026، 14:20.','Validity: 2 November 2026, 14:20 to 5 November 2026, 14:20.')} <bdi dir="ltr">Africa/Cairo · UTC+02:00</bdi></p><div class="notice"><strong>{t('قُدرة غير متاحة في العرض','Operation unavailable in this review')}</strong><p>{t('قبول المسؤولية مش صرف. إبطال تسجيل الصرف بيحافظ على السجل ومش بيسمح بصرف البند تاني.','Acceptance is not dispensing. Reversal retains history and does not permit dispensing the item again.')}</p></div><button class="button secondary" disabled>{t('تسجيل الصرف غير متاح','Record dispense unavailable')}</button><details><summary>{t('السجل المحدود','Bounded history')}</summary><p>{t('وقائع الصرف والتصحيح بس. اسم المريض وتعليمات الوصفة مش بيظهروا في السجل المحدود.','Actual dispense and correction facts only. Patient name and source instructions are excluded from bounded history.')}</p></details>'''
    elif role=='laboratory':
        heading=t('الفحوصات المسندة','Assigned diagnostics')
        intro=t('مثال بصري للمستقبل. مفيش معمل أو نتائج متصلين هنا.','A future visual specimen. No laboratory or results service is connected here.')
        body=f'''<div class="empty-state">{icon('document')}{badge(t('مستقبلي · غير متاح','Future · unavailable'),'warning')}<h2>{t('خدمة المعمل لسه مش متاحة','Laboratory service is not available yet')}</h2><p>{t('عدم إتاحة الخدمة مش معناه مفيش طلبات أو نتائج. مفيش أعداد أو نتائج مرضى في العرض ده.','An unavailable service does not mean there are no orders or results. No patient counts or results are shown here.')}</p><button class="button secondary" disabled>{t('استقبال الطلبات غير متاح','Receive orders unavailable')}</button></div><div class="pattern-inline"><h3>{t('حدود الحالة المقترحة','Proposed state boundary')}</h3><p>{t('المسودة مش نتيجة نهائية. التحقق والاعتماد صريحين، والتصحيح بيحافظ على المصدر والتاريخ. دي حدود تصميمية للمستقبل، مش عمليات شغّالة.','A draft is not a final result. Verification/finalization is explicit; correction retains source and history. These are future design boundaries, not working operations.')}</p></div>'''
    else:
        heading=t('الأشخاص والجهات','People & organizations')
        intro=t('إدارة تشغيلية بس. مفيش صلاحية لفتح المحتوى السريري.','Operational administration only. No authority to open clinical content.')
        body=f'''<div class="section-line"><h2>{t('الجهات · مثال افتراضي','Organizations · synthetic specimen')}</h2>{badge(t('إدارة غير متصلة','Management not connected'))}</div><article class="work-item">{icon('people')}<div><h3>{t('عيادة الدقي','Dokki Clinic')}</h3><p>{t('عيادة افتراضية · بيانات تشغيلية بس','Synthetic clinic · operational data only')}</p></div><button disabled class="button secondary">{t('إدارة العضويات غير متاحة','Manage memberships unavailable')}</button></article><div class="notice">{icon('lock')}<div><h3>{t('حدود الإدارة','Administration boundary')}</h3><p>{t('الإدارة مش بتقدر تتقمّص حساب مريض أو توقّع أو تنشئ صلاحية رعاية أو تتجاوز حدود الوصول.','Admin cannot impersonate a patient, sign, create a clinical assignment or override access boundaries.')}</p></div></div>'''
    content=f'<main id="main" class="workspace operations-workspace"><div class="page-heading"><div><p class="eyebrow">{t("مساحة تشغيلية","Operational workspace")}</p><h1>{heading}</h1><p>{intro}</p></div></div><section class="operations-plane">{body}</section></main>'
    page(f'{variant}-{role}-{lang}.html',heading,shell(role,lang,variant,content),lang,f'product candidate-{variant} role-{role}')


def review_header(active=''):
    links=[('index.html','Review'),('compare.html','Finalists'),('specimen-ar.html','Components'),('typography.html','Type & marks'),('system.html','System proposal')]
    return '<header class="review-header"><a class="wordmark" href="index.html" dir="ltr">EgyHealth <span>360</span></a><nav aria-label="Review sections">'+''.join(f'<a href="{href}"'+(' aria-current="page"' if href==active else '')+f'>{label}</a>' for href,label in links)+'</nav><span class="proposal-tag">V2 / OWNER REVIEW</span></header>'


def specimen(lang):
    t=lambda a,e:pick(lang,a,e)
    states=[('loading',t('تحميل','Loading')),('empty',t('فاضي','Empty')),('success',t('نجاح','Success')),('error',t('خطأ حقل','Field error')),('denied',t('غير مسموح','Access denied')),('unavailable',t('غير متاح','Unavailable')),('uncertain',t('نتيجة غير مؤكّدة','Uncertain outcome')),('time',t('وقت ملتبس','Ambiguous time'))]
    panels={
        'loading':f'<div class="notice" role="status" aria-live="polite"><span class="skeleton" aria-hidden="true"></span><p>{t("بنحمّل المواعيد… دي مش قائمة فاضية.","Loading appointments… this is not an empty list.")}</p></div>',
        'empty':f'<div class="empty-state">{icon("calendar")}<h3>{t("مفيش مواعيد جاية","No upcoming appointments")}</h3><p>{t("ممكن تراجع مواعيدك السابقة أو تدور على ميعاد جديد.","Review previous appointments or find a new appointment.")}</p>{action(t("دور على ميعاد","Find an appointment"),"secondary","navigation")}</div>',
        'success':f'<div class="notice success" role="status">{icon("check")}<div><h3>{t("ملخص الزيارة اتشارك","Visit summary shared")}</h3><p>{t("د. مريم حسن · 2 نوفمبر 2026، 14:40 · توقيت القاهرة. مشاركة الملخص مش بتشارك المتابعة تلقائيًا.","Dr Mariam Hassan · 2 November 2026, 14:40 · Cairo time. Sharing the summary does not automatically share follow-up.")}</p></div></div>',
        'error':f'<div><label for="recovery-date">{t("تاريخ الميعاد","Appointment date")}</label><input id="recovery-date" value="31/02/2026" dir="ltr" aria-invalid="true" aria-describedby="date-error"><p id="date-error" class="error-text">{t("التاريخ ده مش صحيح. اختار يوم موجود في التقويم.","This date is invalid. Choose a day that exists in the calendar.")}</p></div>',
        'denied':f'<div class="notice" role="status">{icon("lock")}<div><h3>{t("المحتوى مش متاح لحسابك","Content is not available to your account")}</h3><p>{t("ارجع للشغل المسموح لك. مش بنعرض أسماء أو مراجع أو أعداد لمحتوى محمي.","Return to permitted work. Protected identities, references and counts are not displayed.")}</p></div></div>',
        'unavailable':f'<div class="notice"><h3>{t("الخدمة مش متاحة","Service unavailable")}</h3><p>{t("مش بنعرضها كأن مفيش بيانات. مفيش انتقال تلقائي لبيانات التجربة.","This is not an empty data state. There is no automatic fallback to Demo data.")}</p><button disabled class="button secondary">{t("العملية غير متاحة","Operation unavailable")}</button></div>',
        'uncertain':f'<div class="notice warning" role="status">{icon("warning")}<div><h3>{t("مش متأكدين التوقيع اتسجّل ولا لأ","Signing outcome is uncertain")}</h3><p>{t("متعملش توقيع جديد. راجع نفس العملية ومصدرها من مساحة العمل المتصلة. مفيش إعادة تلقائية.","Do not create a new signing operation. Check the same operation and source in the connected workspace. No automatic retry.")}</p>{action(t("راجع طريقة الاسترجاع","Review recovery pattern"),"secondary","uncertain")}</div></div>',
        'time':f'<div class="notice"><div><h3>{t("نفس الساعة، وقتين مختلفين","Same clock time, two different instants")}</h3><p>{t("توقيت القاهرة · رجوع الساعة في 29 أكتوبر 2026","Cairo time · clock change on 29 October 2026")}</p><p><bdi dir="ltr">{t('29 أكتوبر 2026','29 October 2026')} · 23:30 · UTC+03:00</bdi></p><p><bdi dir="ltr">{t('29 أكتوبر 2026','29 October 2026')} · 23:30 · UTC+02:00</bdi></p><p>{t("المدى التالي مرتب زمنيًا مع تاريخ مستقل لكل طرف:","The following range is chronological, with a separate date at each endpoint:")}</p><p class="time-range" dir="ltr">{t('29 أكتوبر 2026','29 Oct 2026')} 23:45 UTC+03:00 → {t('29 أكتوبر 2026','29 Oct 2026')} 23:15 UTC+02:00</p></div></div>'
    }
    content=f'''{review_header('specimen-ar.html')}<main id="main" class="review-main"><p class="eyebrow">{t('مكتبة تفاعلية معزولة · اقتراح','Isolated interaction gallery · proposal')}</p><h1>{t('كل حالة، بمعناها.','Every state means something.')}</h1><p class="lede">{t('نفس القواعد البصرية، مع حدود واضحة لكل مصدر وإجراء.','One visual grammar, with explicit boundaries for every source and action.')}</p><a href="specimen-{'en' if lang=='ar' else 'ar'}.html" lang="{'en' if lang=='ar' else 'ar'}">{'English' if lang=='ar' else 'العربية'}</a><section class="specimen-grid"><div><h2>{t('الأزرار وحدود الإجراء','Buttons & action boundaries')}</h2><div class="button-row">{action(t('راجع التوقيع الخاص','Review private signing'),'primary','sign','lock')}{action(t('راجع المشاركة','Review release'),'secondary','release')}{action(t('راجع الإغلاق','Review closing'),'text','close')}</div><p>{t('الأزرار دي بتفتح شرح للتصميم، ومش بتنّفذ أي عملية سريرية.','These controls open design explanations and perform no clinical operation.')}</p><h3>{t('دلالات الحالة','Status semantics')}</h3><div class="status-row">{badge(t('مسودة خاصة','Private draft'))}{badge(t('متشارك','Shared'),'success')}{badge(t('غير مُراجع','Not reviewed'),'warning')}{badge(t('تصحيح مسجّل','Correction retained'))}</div><h3>{t('تجربة التحقق من الحقل','Field-validation interaction')}</h3><form id="specimen-form" novalidate><label for="specimen-name">{t('اسم للعرض · مطلوب','Display name · required')}</label><input id="specimen-name" autocomplete="off" aria-describedby="name-help name-error"><p id="name-help" class="field-help">{t('تجربة محلية بس. متكتبش بيانات حقيقية.','Local specimen only. Do not enter real data.')}</p><p id="name-error" class="error-text" hidden>{t('اكتب اسم افتراضي علشان تكمّل التجربة.','Enter a synthetic name to continue the specimen.')}</p><button class="button secondary" type="submit">{t('اختبر التحقق','Test validation')}</button><p id="form-result" role="status" data-success="{t('الاسم مناسب للتجربة. مفيش بيانات اتحفظت.','The specimen is valid. No data was saved.')}"></p></form></div><div><h2>{t('مقياس الكثافة','Density specimen')}</h2><label for="density">{t('طريقة العرض','Display mode')}</label><select id="density"><option value="comfortable">{t('مريح للمريض','Patient · comfortable')}</option><option value="compact">{t('مضغوط للشغل','Workspace · compact')}</option></select><div id="density-demo" class="density-demo">{''.join(f'<div class="source-row"><span>{icon("document")}</span><div><strong>{label}</strong><p>{t("مصدر مستقل · توقيت القاهرة","Independent source · Cairo time")}</p></div>{badge(state)}</div>' for label,state in [(t('الملاحظة الخاصة','Private note'),t('محفوظة','Saved')),(t('ملخص الزيارة','Visit summary'),t('مسودة','Draft')),(t('المتابعة','Follow-up'),t('غير مكتوبة','Not authored'))])}</div><p>{t('الكثافة بتغيّر المسافات، مش حجم اللمس أو معنى الحالة.','Density changes spacing, while targets and state meanings remain stable.')}</p><h3>{t('تمييز وضع الخدمة','Service-mode distinction')}</h3><div class="mode-specimens"><span class="demo-label">{t('عرض تجريبي · بيانات افتراضية','Demo · synthetic data')}</span><span class="live-specimen">{t('خدمة فعلية · مثال مظهر بس','Live · appearance specimen only')}</span></div></div></section><section class="states-section"><h2>{t('حالات لازم تبقى واضحة','States that must stay clear')}</h2><p>{t('اختار حالة. تغيير الاختيار بيغيّر المثال المعروض بس.','Choose a state. Selection changes only the displayed specimen.')}</p><label for="state">{t('الحالة','State')}</label><select id="state">{''.join(f'<option value="{key}">{label}</option>' for key,label in states)}</select>{''.join(f'<section class="state-panel" id="state-{key}" aria-label="{dict(states)[key]}"'+(' hidden' if key!='loading' else '')+f'>{panel}</section>' for key,panel in panels.items())}</section><section><h2>{t('اسم طويل بالعربي','Long Arabic content')}</h2><div class="long-content" lang="ar" dir="rtl"><h3>عمر محمد أحمد عبدالرحمن عبدالعزيز مصطفى السيد</h3><p>المعلومات اللي الدكتور شاركها معاك بتظهر حسب صلاحية الوصول الحالية. الملاحظة الخاصة مش جزء من ملخص الزيارة، والتوصية بمتابعة مش حجز ميعاد جديد.</p><p><bdi dir="ltr">Amoxicillin · 1.25 mL</bdi> — كمية عرض افتراضية، مش تعليمات جرعة.</p></div></section></main>{preview_dialog(lang)}'''
    page(f'specimen-{lang}.html',t('المكونات والحالات','Components & states'),content,lang)


def index():
    content=f'''{review_header('index.html')}<main id="main" class="review-main"><div class="review-hero"><div><p class="eyebrow">DESIGN FOUNDATION / 06 NOVEMBER 2026</p><h1>Human warmth.<br>Clinical precision.</h1><p class="lede">A shared identity for people receiving care and the professionals responsible for it. Two coherent finalists, one considered recommendation.</p><div class="button-row"><a class="button primary" href="compare.html">Compare the finalists {icon('arrow')}</a><a class="button secondary" href="h-patient-ar.html" lang="ar">شوف متابعتي بالعربي {icon('arrow')}</a></div><p class="review-boundary">Exploratory, synthetic and isolated. No Final Brand, logo, font, component API or product decision is frozen.</p></div><div class="thesis-mark" aria-hidden="true"><span class="thesis-number">360</span><span class="thesis-rule"></span><p lang="ar" dir="rtl">كل خطوة واضحة.<br>وكل معلومة في سياقها.</p><small>VISUAL STUDY / NOT A TAGLINE</small></div></div><section class="finalist-cards"><article class="finalist-card"><p class="eyebrow">H / RECOMMENDED FOR OWNER SELECTION</p><h2>Human Precision</h2><p>E’s authored Arabic and attentive patient rhythm. D’s ruled source hierarchy. F’s persistent context, expressed on light surfaces.</p><a href="h-patient-ar.html"><img src="evidence/h-patient-ar-1440.png" alt="Human Precision Arabic patient desktop preview" width="1440" height="1000"></a><div class="button-row"><a href="h-patient-ar.html">Patient AR</a><a href="h-patient-en.html">EN</a><a href="h-clinician-ar.html">Doctor AR</a><a href="h-clinician-en.html">EN</a></div></article><article class="finalist-card"><p class="eyebrow">P / CHALLENGER</p><h2>Precision, Open</h2><p>A quieter rail and calendar-led composition, with one continuous care plane. Less service expression, more repeatable scanning.</p><a href="p-patient-ar.html"><img src="evidence/p-patient-ar-1440.png" alt="Precision Open Arabic patient desktop preview" width="1440" height="1000"></a><div class="button-row"><a href="p-patient-ar.html">Patient AR</a><a href="p-patient-en.html">EN</a><a href="p-clinician-ar.html">Doctor AR</a><a href="p-clinician-en.html">EN</a></div></article></section><section class="review-section"><p class="eyebrow">ONE IDENTITY / DIFFERENT RESPONSIBILITIES</p><h2>Beyond two screens.</h2><div class="role-links">{''.join(f'<a class="role-link" href="h-{r}-ar.html"><span>{icon(i)}</span><strong>{name}</strong><span>{scope}</span>{icon("arrow")}</a>' for r,i,name,scope in [('pharmacy','rx','Pharmacy','Assigned items, bounded history'),('laboratory','document','Laboratory','Future / unavailable specimen'),('admin','people','Admin','People & organizations only')])}</div><p>English and challenger equivalents are linked in the <a href="compare.html">complete screen inventory</a>. Operations remain honest non-working specimens.</p></section><section class="recommendation"><p class="eyebrow">THE RECOMMENDATION</p><h2>Choose H’s grammar, then refine its details.</h2><p>H best balances the accepted calm, attentive and precise personality across both roles. Its advantage is composition and source clarity—not a new color. P remains a credible choice when operational neutrality matters more.</p><p>Owner options: <b>H / P / reject both / named hybrid</b>. Logo and typography choices remain separate. The next phase starts only after visual-DNA selection.</p><a href="RATIONALE.md">Read the scorecard, evidence and tradeoffs {icon('arrow')}</a></section><section class="review-section"><h2>Review the complete foundation</h2><div class="review-links"><a href="specimen-ar.html">01 · Interactive components & states</a><a href="typography.html">02 · Arabic / Latin type & logo studies</a><a href="system.html">03 · Layered token & pattern architecture</a><a href="ACCESSIBILITY.md">04 · Accessibility evidence & limits</a><a href="IMPLEMENTATION_PLAN.md">05 · Sequenced adoption proposal</a></div></section><footer class="review-end">Based on verified main <code>{BASE[:7]}</code> · Original D/E/F, Patient and Clinician evidence preserved.</footer></main>'''
    page('index.html','Human Precision · visual review',content)


def compare():
    tiles=[]
    for v,name in [('h','Human Precision'),('p','Precision, Open')]:
        blocks=''
        for role,label in [('patient','Patient'),('clinician','Clinician')]:
            blocks+=f'<h3>{label} / Arabic</h3><a href="{v}-{role}-ar.html"><img src="evidence/{v}-{role}-ar-1440.png" width="1440" height="1000" alt="{name} {label} Arabic desktop"></a><div class="mobile-pair"><a href="{v}-{role}-ar.html"><img src="evidence/{v}-{role}-ar-390.png" width="390" height="844" alt="{name} {label} Arabic mobile"></a><a href="{v}-{role}-en.html"><img src="evidence/{v}-{role}-en-390.png" width="390" height="844" alt="{name} {label} English mobile"></a></div><p><a href="{v}-{role}-ar.html">Open Arabic</a> · <a href="{v}-{role}-en.html">Open English</a> · <a href="evidence/{v}-{role}-ar-1440-full.png">Full desktop PNG</a> · <a href="evidence/{v}-{role}-ar-390-full.png">Full mobile PNG</a></p>'
        tiles.append(f'<article class="comparison-column"><p class="eyebrow">{v.upper()} / UNSELECTED</p><h2>{name}</h2>{blocks}</article>')
    inventory='<table><caption>All full-size responsive screens</caption><thead><tr><th>Role</th><th>H Arabic</th><th>H English</th><th>P Arabic</th><th>P English</th></tr></thead><tbody>'+''.join(f'<tr><th>{role.title()}</th>'+''.join(f'<td><a href="{v}-{role}-{lang}.html">{v.upper()} · {lang.upper()}</a></td>' for v in ['h','p'] for lang in ['ar','en'])+'</tr>' for role in ['patient','clinician','pharmacy','laboratory','admin'])+'</tbody></table>'
    page('compare.html','Finalist comparison',review_header('compare.html')+f'<main id="main" class="review-main"><p class="eyebrow">EQUAL CONTENT / EQUAL VIEWPORTS</p><h1>Two grammars.<br>One care story.</h1><p class="lede">Both use the committed D/E/F synthetic facts, accepted navigation and independent source meanings. Patient context is 2 November 2026; these are dated design fixtures.</p><div class="comparison-grid">{"".join(tiles)}</div><section class="review-section">{inventory}</section><section><h2>Original evidence, at its original paths</h2><div class="role-links">'+''.join(f'<a class="role-link" href="../visual-directions-v2/direction-{d}/index.html"><strong>{d.upper()} · {name}</strong><img src="../visual-directions-v2/direction-{d}/board.png" width="1600" height="1700" alt="Original {name} board"></a>' for d,name in [('d','Precision Health'),('e','Human Clinical'),('f','Next-Gen Health OS')])+f'</div><p><a href="../ui-reference/polish-evidence/patient-my-care-desktop-ar.png">Merged Patient evidence</a> · <a href="../ui-reference/clinician-premium-evidence/after/desktop-en.png">Merged Clinician evidence</a> · <a href="RATIONALE.md">Comparative scorecard</a></p></section></main>')


def typography():
    families=[('human-type','Manrope + IBM Plex Sans Arabic','Warm bilingual rhythm; H proposal, inherited from E and merged visual work.'),('precision-type','Inter + Noto Sans Arabic','Neutral scanning; P proposal, inherited from D. Arabic line height remains generous.'),('os-type','IBM Plex Sans + Noto Sans Arabic','F comparison; useful numeric rhythm, less expressive patient voice.')]
    typecards=''.join(f'<article class="type-card {cls}"><p class="eyebrow">{name}</p><h2 lang="ar" dir="rtl">متابعتك أوضح، وكل خطوة في مكانها.</h2><h2>Your care, with context.</h2><p lang="ar" dir="rtl">د. مريم حسن · ملخص الزيارة · الملاحظة الخاصة بتفضل خاصة.</p><p>{desc}</p><p class="numeral" dir="ltr">0123456789 · 14:30 · 1.25 mL</p><p lang="ar" dir="rtl">كمية عرض افتراضية: <bdi dir="ltr">Amoxicillin · 1.25 mL</bdi>، مش جرعة.</p><p lang="ar" dir="rtl">مُلَخَّص الزِّيارة · عمر محمد أحمد عبدالرحمن عبدالعزيز مصطفى السيد</p></article>' for cls,name,desc in families)
    marks=''
    for key,label,reason in [('e1','E1 · Shared support','Open support; strongest warmth, but U/furniture resemblance remains.'),('d1','D1 · Aligned custody','Distinct custody gap; strongest small-size geometry, but logistics resemblance remains.')]:
        mark=(HERE.parent/f'visual-directions-v2/assets/{key}.svg').read_text()
        # Inline preserved vector with inherited currentColor for true monochrome/inverse proofs.
        import re
        mark=re.sub(r'<\?xml[^>]*>', '', mark)
        mark=re.sub(r'fill="#[0-9a-fA-F]+"','fill="currentColor"',mark)
        marks+=f'<article class="mark-card"><h3>{label}</h3><p>{reason}</p><div class="mark-sizes">'+''.join(f'<div><span class="mark m{size}">{mark}</span><span>{size}px</span></div>' for size in [16,24,32])+f'</div><div class="mark-background mono"><span class="mark m32">{mark}</span><span dir="ltr">EgyHealth 360</span><small>Monochrome</small></div><div class="mark-background inverse"><span class="mark m32">{mark}</span><span dir="ltr">EgyHealth 360</span><small>Inverse</small></div></article>'
    page('typography.html','Type and mark explorations',review_header('typography.html')+f'<main id="main" class="review-main"><p class="eyebrow">PROVISIONAL / NO FONT OR LOGO SELECTION</p><h1>Arabic sets the rhythm.</h1><p class="lede">Compare joining, diacritics, long names, mixed clinical strings and numerals. Every font is local, existing and licensed; no new service or asset dependency.</p><section class="type-grid">{typecards}</section><section class="review-section"><h2>A wordmark first. Symbols still open.</h2><p>The proposed screens use the text wordmark only, preserving the merged identity boundary. E1 and D1 are retained exploration seeds, never an implicit logo selection.</p><article class="mark-card wordmark-study"><h3>Text-only control</h3><div class="wordmark-sizes"><span style="font-size:16px" dir="ltr">EgyHealth 360</span><span style="font-size:24px" dir="ltr">EgyHealth 360</span><span style="font-size:32px" dir="ltr">EgyHealth 360</span></div><div class="mark-background inverse"><strong dir="ltr">EgyHealth 360</strong><span lang="ar" dir="rtl">متابعتي</span></div></article><div class="type-grid">{marks}</div><p>16px proofs are actual CSS sizes. Inspect at browser 100%, not the scaled review-board thumbnail. No recognition, legal clearance or trademark claim. <a href="../visual-directions-v2/logos.html">All six original concepts</a>.</p></section></main>')


def system_page():
    sections=[('01','Foundation','Local bilingual type, restrained navy/teal, neutral light planes, 4px sub-rhythm / 8px layout rhythm. Existing evidence supplies each proposal.'),('02','Semantic intent','Canvas, surface, text, action, focus, private audience, release audience, warning, error, success. Brand teal never means “clinically normal”.'),('03','Component decisions','Action, field, status, source row, context ribbon, audience boundary and confirmation. Proposed taxonomy only; no React API is frozen.'),('04','Usage modes','Patient: attentive spacing and one appointment anchor. Clinician: compact source divisions. Operations: aligned work rows with exact artifact scope.'),('05','Responsive behavior','1440+ constrained canvas; 768 tablet reflow; 390 and 320 single-column patient context. Below 720, clinician becomes visit review, not squeezed signing.'),('06','Motion & focus','140ms color feedback, no animated clinical success. Reduced-motion removes transitions. 3px dark focus ring with a 3px surface gap.')]
    content=review_header('system.html')+'<main id="main" class="review-main"><p class="eyebrow">PROPOSED ARCHITECTURE / V0.1</p><h1>One grammar.<br>Room for real work.</h1><p class="lede">A vendor-neutral DTCG-compatible proposal: foundational values → semantic intent → component decisions. Density changes without changing identity or authority.</p><div class="system-layers">'+''.join(f'<section><span class="layer-number">{n}</span><div><h2>{name}</h2><p>{text}</p></div></section>' for n,name,text in sections)+'</div><section class="review-section"><h2>Tokens you can inspect</h2><div class="swatch-grid">'+''.join(f'<div><span style="background:{color}"></span><strong>{name}</strong><code>{color}</code></div>' for name,color in [('Ink','#102A38'),('Action','#155E63'),('Canvas','#F5F7F7'),('Surface','#FFFFFF'),('Muted','#4E626B'),('Warning ink','#765000')])+'</div><p><a href="tokens.json">DTCG token proposal</a> · <a href="SYSTEM_FOUNDATION.md">Taxonomy, responsive and healthcare pattern specification</a> · <a href="ACCESSIBILITY.md">Contrast matrix and verification limits</a></p><p>The generated CSS resolves semantic aliases. P changes composition and uses its own explicit semantic overrides, not an ad hoc second component library.</p></section><section class="recommendation"><h2>Preserve independent consequences.</h2><p>Saving, private signing, summary release, follow-up release, prescription signing and irreversible close remain separate. Visual continuity never creates shared clinical authority.</p><p>Laboratory remains future. Pharmacy operations are unconnected specimens. Admin has no clinical payload or override. No AI or EACCE action is invented.</p></section></main>'
    page('system.html','System foundation proposal',content)


if __name__ == '__main__':
    for variant in ['h','p']:
        for lang in ['ar','en']:
            patient(lang,variant)
            clinician(lang,variant)
            for role in ['pharmacy','laboratory','admin']:
                operations(role,lang,variant)
    for lang in ['ar','en']:
        specimen(lang)
    index()
    compare()
    typography()
    system_page()
    write('evidence/inventory.json',json.dumps({'base':BASE,'screens':INVENTORY},ensure_ascii=False,indent=2)+'\n')
